function cercoClose(){const now=Date.now();Q('SELECT st FROM cerco UNION SELECT cs FROM cryst WHERE cs>1').filter(r=>r.st&&r.st+CERCO_WIN<=now&&!Q1('SELECT 1 x FROM cercoend WHERE st=?',r.st)).forEach(r=>{X('INSERT OR IGNORE INTO cercoend(st) VALUES(?)',r.st);const top=cercoRank(r.st).slice(0,3),m=['🥇','🥈','🥉'];let txt='';if(top.length)txt='🏰 Cerco de Tangamandapio encerrado! '+top.map((t,i)=>m[i]+' Guilda '+t.g+' ('+t.k+' abates)').join(' · ');if(r.st>1e12){const kk=Object.fromEntries(Q('SELECT g,k FROM cerco WHERE st=?',r.st).map(x=>[String(x.g).toLowerCase(),x.k]));let cr=Q('SELECT kg g,COUNT(*) c FROM cryst WHERE cs=? AND COALESCE(kg,\'\')<>\'\' AND kg NOT LIKE \'#%\' GROUP BY kg COLLATE NOCASE',r.st).map(x=>({g:x.g,c:x.c,k:kk[String(x.g).toLowerCase()]||0}));cr.sort((a,b)=>b.c-a.c||b.k-a.k);const pt=PDL_PTS[cercoKind(r.st)],pay=(g,p,wn)=>{X('INSERT INTO gdpdl(g,pdl,wins,at) VALUES(?,?,?,?) ON CONFLICT(g) DO UPDATE SET pdl=pdl+?,wins=wins+?,at=?',g,p,wn,now,p,wn,now);X('INSERT INTO gdpdlm(ym,g,pdl) VALUES(?,?,?) ON CONFLICT(ym,g) DO UPDATE SET pdl=pdl+?',ymOf(r.st),g,p,p)};if(cr.length){cr.forEach((x,i)=>pay(x.g,pt*x.c,i===0?1:0));txt+=(txt?' · ':'🏰 Cerco encerrado! ')+cr.slice(0,3).map((x,i)=>(i?'':'🏆 ')+'Guilda '+x.g+' defendeu '+x.c+' cristal(is) (+'+(pt*x.c)+' PDL)').join(' · ')}else if(top[0]){pay(top[0].g,pt,1);txt+=(txt?' · ':'🏰 Cerco encerrado! ')+'🏆 Guilda '+top[0].g+' venceu (+'+pt+' PDL)'}}if(!txt)return;txt=txt.replace(/[<>&|]/g,'').slice(0,200);X('INSERT INTO announces(uid,name,txt,k,at) VALUES(?,?,?,?,?)',0,'GVG',txt,'gl|#ffd24a|Impact',now)})}
